function drawCover(img,w,h){const iw=Math.max(1,img.naturalWidth||img.width||w);const ih=Math.max(1,img.naturalHeight||img.height||h);const scale=Math.max(w/iw,h/ih);const dw=iw*scale,dh=ih*scale;ctx.drawImage(img,(w-dw)/2,(h-dh)/2,dw,dh);}
function box(x,y,w,h){const b=GS.glassBox;ctx.save();rr(x,y,w,h,b.radius);const g=ctx.createLinearGradient(x,y,x,y+h);g.addColorStop(0,b.fillTop);g.addColorStop(b.sheenRatio,b.fillMiddle);g.addColorStop(1,b.fillBottom);ctx.fillStyle=g;ctx.fill();ctx.strokeStyle=b.borderColor;ctx.lineWidth=b.borderWidth;ctx.stroke();ctx.save();rr(x+2,y+2,w-4,(h-4)*b.sheenClipRatio,b.insetRadius);ctx.clip();const sheen=ctx.createLinearGradient(x,y,x,y+h*b.sheenRatio);sheen.addColorStop(0,b.sheenTop);sheen.addColorStop(1,b.sheenBottom);ctx.fillStyle=sheen;ctx.fillRect(x+2,y+2,w-4,h*b.sheenRatio);ctx.restore();ctx.restore();}
