function legendLayout(value,maxWidth,maxHeight){const paragraphs=normalizeMultiline(value).split(/\\n\\s*\\n/).map(part=>part.trim()).filter(Boolean).slice(0,3);for(let size=72;size>=42;size--){const lineHeight=Math.round(size*1.19),separatorSpace=Math.round(size*1.82),emojiInset=Math.round(size*1.15);const blocks=paragraphs.map((part,index)=>{const parsed=index===0?splitLegendEmoji(part):{emoji:'',text:part};return{emoji:parsed.emoji,lines:legendParagraphLines(parsed.text,maxWidth,size,400,index===0&&parsed.emoji?emojiInset:0)};});const lines=blocks.reduce((sum,block)=>sum+block.lines.length,0);const height=lines*lineHeight+Math.max(0,blocks.length-1)*separatorSpace;if(height<=maxHeight)return{size,lineHeight,separatorSpace,emojiInset,blocks,height};}const size=42,lineHeight=50,separatorSpace=76,emojiInset=48,blocks=paragraphs.map((part,index)=>{const parsed=index===0?splitLegendEmoji(part):{emoji:'',text:part};return{emoji:parsed.emoji,lines:legendParagraphLines(parsed.text,maxWidth,size,400,index===0&&parsed.emoji?emojiInset:0)};});const lines=blocks.reduce((sum,block)=>sum+block.lines.length,0);return{size,lineHeight,separatorSpace,emojiInset,blocks,height:lines*lineHeight+Math.max(0,blocks.length-1)*separatorSpace};}
function drawLegendSerifLine(value,x,y,size){ctx.save();legendFont(size,400);ctx.fillStyle=INK;ctx.strokeStyle=INK;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.lineJoin='round';ctx.miterLimit=2;ctx.lineWidth=.34;ctx.strokeText(value,x,y);ctx.fillText(value,x,y);ctx.restore();}
function drawLegendEmoji(value,x,y,size){if(!value)return;ctx.save();ctx.font=String(Math.round(size*.82))+'px '+EMOJI_FONT;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillText(value,x,y);ctx.restore();}
function drawLegendAccent(y){ctx.save();ctx.strokeStyle=GOLD;ctx.lineWidth=4;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(455,y);ctx.lineTo(625,y);ctx.stroke();ctx.restore();}
function drawLegendPanel(frame=STORY_FRAME.deck.body){const value=m.legendText||[m.social?.paragraph1,m.social?.paragraph2].filter(Boolean).join('\\n\\n'),paddingX=58,paddingY=72,x=frame.x+paddingX,w=frame.width-paddingX*2,areaTop=frame.y+paddingY,areaHeight=frame.height-paddingY*2,layout=legendLayout(value,w,areaHeight);let yy=areaTop+Math.max(0,(areaHeight-layout.height)/2)+layout.size;layout.blocks.forEach((block,index)=>{block.lines.forEach((line,lineIndex)=>{const inset=index===0&&lineIndex===0&&block.emoji?layout.emojiInset:0;if(index===0&&lineIndex===0&&block.emoji)drawLegendEmoji(block.emoji,x,yy,layout.size);drawLegendSerifLine(line,x+inset,yy,layout.size);yy+=layout.lineHeight;});if(index<layout.blocks.length-1){const lineY=yy+Math.round(layout.separatorSpace*.24);drawLegendAccent(lineY);yy+=layout.separatorSpace;}});}
