async function draw(){window.__LOKA_RENDER_STATUS={started:true,storyRendered:false,hourlyStoryRendered:false,hourlyLateStoryRendered:false,daylightStoryRendered:false,moonStoryRendered:false,legendRendered:false,comparisonRendered:false,feedRendered:false,error:null};const slots=pickHourlySlots(m.hourly);const bg=await load(m.masterUrl,'background');const logo=await load(m.brand.logoUrl,'logo');const mainIcon=await load(m.scene.pictogramUrl,'main_pictogram');const comparisonIcon=m.comparison?await load(m.comparison.pictogramUrl,'comparison_pictogram'):null;const hourIcons=await Promise.all(slots.map((item,index)=>load(item.pictogramUrl,'hourly_pictogram_'+index)));const deckHourIcons=await Promise.all(m.storyDeck.hourly.points.map((item,index)=>item.pictogramUrl?load(item.pictogramUrl,'story_hourly_pictogram_'+index):Promise.resolve(null)));const moonIcon=await load(m.storyDeck.moon.pictogramUrl,'moon_pictogram');const solarIcons={dawn:await load(m.solarPictograms.dawn,'solar_dawn'),sunrise:await load(m.solarPictograms.sunrise,'solar_sunrise'),noon:await load(m.solarPictograms.noon,'solar_noon'),sunset:await load(m.solarPictograms.sunset,'solar_sunset'),dusk:await load(m.solarPictograms.dusk,'solar_dusk')};renderStory(bg,logo,mainIcon,slots,hourIcons,solarIcons);window.__LOKA_RENDER_STATUS.storyRendered=true;renderHourlyStory(hourlyStoryCtx,bg,logo,m.storyDeck.hourly.points.slice(0,10),deckHourIcons.slice(0,10),'HOURLY_EARLY');window.__LOKA_RENDER_STATUS.hourlyStoryRendered=true;renderHourlyStory(hourlyLateStoryCtx,bg,logo,m.storyDeck.hourly.points.slice(10,20),deckHourIcons.slice(10,20),'HOURLY_LATE');window.__LOKA_RENDER_STATUS.hourlyLateStoryRendered=true;renderDaylightStory(bg,logo,solarIcons);window.__LOKA_RENDER_STATUS.daylightStoryRendered=true;renderMoonStory(bg,logo,moonIcon);window.__LOKA_RENDER_STATUS.moonStoryRendered=true;renderLegendStory(bg,logo);window.__LOKA_RENDER_STATUS.legendRendered=true;if(comparisonIcon){renderComparisonStory(bg,logo,comparisonIcon);window.__LOKA_RENDER_STATUS.comparisonRendered=true;}renderFeed(bg,logo,mainIcon,slots,hourIcons,solarIcons);window.__LOKA_RENDER_STATUS.feedRendered=true;window.__LOKA_RENDER_STATUS.rendered=true;const deckButton=document.getElementById('shareStoryDeck'),deckStatus=document.getElementById('storyDeckStatus');deckButton.disabled=false;deckButton.textContent='Partager / enregistrer les 6 stories';deckStatus.textContent=m.storyDeck.hourly.complete?'Story principale préservée · 5 compléments prêts à tester.':'Story principale préservée · compléments prêts, avec les heures indisponibles marquées « — ».';window.__LOKA_STORY_DECK_AUDIT={version:m.storyDeck.version,frame:m.storyDeck.frame,order:['PRIMARY','HOURLY_04_13','HOURLY_14_23','DAYLIGHT','MOON','PUBLICATION_LEGEND'],storyCount:6,width:1080,height:1920,hourRange:[m.storyDeck.hourly.startHour,m.storyDeck.hourly.endHour],hourlyComplete:m.storyDeck.hourly.complete,primaryStoryPreserved:true,storyOneEditorialSource:'PRIMARY_SECONDARY',storySixEditorialSource:'PUBLICATION_LEGEND',publicationChanged:false};window.__LOKA_EDITORIAL_AUDIT={sceneId:m.scene.id,title:m.scene.canonicalTitle,displayTitle:m.scene.title,rendererReclassified:false};window.__LOKA_BRAND_AUDIT={logoUrl:m.brand.logoUrl};window.__LOKA_PICTOGRAM_AUDIT={version:m.pictogramLibrary.version,ink:m.pictogramLibrary.ink,gold:m.pictogramLibrary.gold,mainSceneId:m.scene.id};}
function fallbackCopy(value){const area=document.createElement('textarea');area.value=value;area.setAttribute('readonly','');area.style.position='fixed';area.style.opacity='0';document.body.appendChild(area);area.select();area.setSelectionRange(0,area.value.length);let ok=false;try{ok=document.execCommand('copy');}catch{}area.remove();return ok;}
async function copyText(value,label){let ok=false;try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(value);ok=true;}}catch{}if(!ok)ok=fallbackCopy(value);const status=document.getElementById('copyStatus');status.textContent=ok?label+' copié.':'Copie impossible : sélectionne le texte manuellement.';setTimeout(()=>{if(status.textContent.startsWith(label))status.textContent='';},1800);}
function canvasFile(targetCanvas,suffix){return new Promise(resolve=>targetCanvas.toBlob(blob=>resolve(blob?new File([blob],'loka-'+String(m.date||'meteo')+'-'+suffix+'.png',{type:'image/png'}):null),'image/png'));}
function fallbackDownload(file){const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=file.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function shareCanvas(targetCanvas,suffix){const file=await canvasFile(targetCanvas,suffix);if(!file)return;if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){try{await navigator.share({files:[file],title:'LOKA!'});return;}catch(error){if(error?.name==='AbortError')return;}}fallbackDownload(file);}
const STORY_DECK_EXPORTS=[[storyCanvas,'story-01-journee'],[hourlyStoryCanvas,'story-02-fil-04-13'],[hourlyLateStoryCanvas,'story-03-fil-14-23'],[daylightStoryCanvas,'story-04-heures-du-jour'],[moonStoryCanvas,'story-05-lune'],[legendStoryCanvas,'story-06-legende-publication']];
async function shareStoryDeck(){const button=document.getElementById('shareStoryDeck'),status=document.getElementById('storyDeckStatus');if(!window.__LOKA_RENDER_STATUS?.rendered)return;button.disabled=true;button.textContent='Préparation des fichiers…';status.textContent='Création des six images dans le bon ordre.';try{const files=(await Promise.all(STORY_DECK_EXPORTS.map(item=>canvasFile(item[0],item[1])))).filter(Boolean);if(files.length!==6)throw new Error('story_deck_export_incomplete');if(navigator.share&&(!navigator.canShare||navigator.canShare({files}))){try{await navigator.share({files,title:'LOKA! · Stories du jour'});status.textContent='Les 6 stories ont été transmises dans l’ordre.';return;}catch(error){if(error?.name==='AbortError'){status.textContent='Partage annulé.';return;}}}files.forEach(file=>fallbackDownload(file));status.textContent='Les 6 stories ont été téléchargées dans l’ordre 1 à 6.';}catch(error){status.textContent='Export impossible : '+String(error);}finally{button.disabled=false;button.textContent='Partager / enregistrer les 6 stories';}}
